cd /app && cat > assemble.py <<'EOF'
import glob,re,collections,difflib
files=sorted(glob.glob('/app/frames/all/f*.txt'))
frames=[]
for fp in files:
    idx=int(re.search(r'f(\d+)\.txt',fp).group(1))
    lines=open(fp,errors='ignore').read().splitlines()
    N=None
    for line in lines:
        m=re.search(r'Moves:\s*(\d+)',line,re.I)
        if m:
            v=int(m.group(1))
            if 0<=v<=300: N=v
            break
    if N is None or N<1: continue
    cmds=[]
    for i,line in enumerate(lines):
        s=line.strip()
        mm=re.match(r'^[>»]\s*(.*)$',s)
        if mm:
            c=mm.group(1).strip(' _')
            if c and re.match(r"^[A-Za-z0-9 ,.'!?_-]+$",c):
                out=any(x.strip() for x in lines[i+1:])
                cmds.append((c,out))
    if not cmds: continue
    if not cmds[-1][1]: cmds=cmds[:-1]
    if cmds: frames.append((N,[c for c,_ in cmds]))

def norm(c):
    c=c.lower().strip(' .,')
    c=re.sub(r'^(d|j|f|a)(?=[a-z])',lambda m:m.group(1),c) if False else c
    fixes={'def late boat':'inflate boat','drpo boat':'drop boat','eage':'cage','ulysse':'ulysses','lig':'light lamp','ca':'case'}
    c=fixes.get(c,c)
    return c
def sim(a,b):
    return difflib.SequenceMatcher(None,a,b).ratio()>=0.72
maxN=max(n for n,_ in frames)
S=[None]*(maxN+3)
votes=[collections.Counter() for _ in range(maxN+3)]
for it in range(4):
    for N,C in sorted(frames):
        p=N
        for j in range(len(C)-1,-1,-1):
            c=norm(C[j])
            best=None
            for q in range(p,max(0,p-5),-1):
                if S[q] is not None and sim(S[q],c): best=q; break
            if best is not None:
                votes[best][c]+=1; p=best-1
            elif S[p] is None:
                votes[p][c]+=1; S[p]=c; p-=1
            else:
                p-=1
# choose votes, propagate gaps
for i in range(1,maxN+1):
    if votes[i]: S[i]=votes[i].most_common(1)[0][0]
print('maxN',maxN,'known',sum(1 for i in range(1,maxN+1) if S[i]))
with open('/tmp/seq.txt','w') as f:
    for i in range(1,maxN+1):
        f.write(f'{i}: {S[i]}\n')
EOF
